/**
 * A baked-in synthetic QR code, used by the native engine's availability probe.
 *
 * The native `BarcodeDetector` can be present-but-broken (pre-Chrome-113 macOS
 * Ventura silently returns `[]`) or shadowed by a polyfill. So before trusting
 * it, we decode a known QR and check we get the expected payload back. We bake
 * the QR's *module matrix* (1 bit per module) rather than a PNG, so there is no
 * image decoder and no QR encoder in the runtime bundle — just these bytes and
 * the tiny expander below.
 *
 * The constants below are generated by `pnpm gen:probe`.
 */
import type { FrameImage } from "./types.js";

export const PROBE_PAYLOAD = "qrdu-probe";

// --- generated by scripts/gen-probe.mjs (do not edit by hand) ---------------
/** Module count per side (QR is square). */
export const PROBE_SIZE = 21;
/** Row-major modules packed 8-per-byte, MSB first; 1 = dark module. base64. */
export const PROBE_MATRIX_BASE64 = "/sv8ERBupLt0RdukrsFRB/qv4AIAo1kq4TTj8DND2aV2XYB47/rzsE6Jun2V0i4usK8EEg/sZIA=";
// --- end generated ----------------------------------------------------------

function decodeBase64(b64: string): Uint8Array {
  // atob exists in browsers, Web Workers, and Node >=18.
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/**
 * Expand the baked matrix into a `FrameImage`, scaling each module to
 * `scale` px and surrounding it with a `quiet`-module light border (QR needs a
 * quiet zone to be decodable).
 */
export function getProbeFrame(scale = 8, quiet = 4): FrameImage {
  const size = PROBE_SIZE;
  const bits = decodeBase64(PROBE_MATRIX_BASE64);
  const isDark = (r: number, c: number): boolean => {
    if (r < 0 || c < 0 || r >= size || c >= size) return false;
    const idx = r * size + c;
    const byte = bits[idx >> 3] ?? 0;
    return ((byte >> (7 - (idx & 7))) & 1) === 1;
  };

  const modules = size + quiet * 2;
  const px = modules * scale;
  const data = new Uint8ClampedArray(px * px * 4);
  data.fill(255); // white background (includes quiet zone)

  for (let r = 0; r < size; r++) {
    for (let c = 0; c < size; c++) {
      if (!isDark(r, c)) continue;
      const y0 = (r + quiet) * scale;
      const x0 = (c + quiet) * scale;
      for (let y = y0; y < y0 + scale; y++) {
        for (let x = x0; x < x0 + scale; x++) {
          const o = (y * px + x) * 4;
          data[o] = 0;
          data[o + 1] = 0;
          data[o + 2] = 0;
          data[o + 3] = 255;
        }
      }
    }
  }

  return { data, width: px, height: px };
}
